  // ---- god ----
  const GOD_SYM = Symbol.for("jshack:debug:godMode");
  function toggleGodMode() {
    world[GOD_SYM] = !world[GOD_SYM];
    const pe = playerEntity(world);
    if (!pe) return 'No player entity found.';
    if (world[GOD_SYM]) {
