function applyScavenge(world, id, nutrition) {
  const heal = Math.max(1, Math.floor(nutrition / 100));
  const actual = applyHealing(world, { target: id, amount: heal, source: id, cause: 'scavenge' }).amount;
  return { healAmount: actual };
