    // Behaviour-specific guard
    const vit = world.get(id, Vitality);
    if (!vit || (vit.hp | 0) <= 0) return;

    if (behavior === "scavenge") {
      const threshold = config.hpThreshold ?? 0.75;
      if ((vit.hp / Math.max(1, vit.maxHp)) >= threshold) return;
    }

