    let corpseId = null;
    forEachInRadius(world, pos.x | 0, pos.y | 0, 1, (itemId) => {
      if (corpseId !== null) return;
      if (consumed.has(itemId)) return;
      if (isCorpseOnFloor(world, itemId)) corpseId = itemId;
