// src/rules/systems/channelingSystem.js
// Counts down active channel timers each tick. Completed item use-actions
// dispatch through the registry; completed spell casts inject CastSpellIntent.
// Cancellation from the app layer (ESC) removes Channeling directly.

import { Channeling } from "../components/Channeling.js";
import { ActiveEffects } from "../components/ActiveEffects.js";
import { CastSpellIntent } from "../components/Intents/CastSpellIntent.js";
import { Mana } from "../components/Mana.js";
import { Stamina } from "../components/Stamina.js";
import { Position } from "../components/Position.js";
import { Vitality } from "../components/Vitality.js";
import { getUseAction } from "../content/useActions/useActionRegistry.js";
import { getSpell } from "../data/spells.js";
import { MANA_REGEN_COOLDOWN, STAMINA_REGEN_COOLDOWN } from "../data/regenConstants.js";
import { runSpellScript } from "../scripts/spells.js";
import { effectiveMaxMana, effectiveMaxStamina } from "../utils/passiveBonuses.js";
import { getChannelInterruptionReason } from "../utils/channelInterruptionPolicy.js";
import { hasLOS } from "../../shared/math/gridLOS.js";
import { buildBlocksVisionMap, blockedCallback } from "../utils/vision.js";
import { spellCostPerTick, spellCostResource } from "../data/spells.js";

export function applyDrainLifeDamageInterrupt(world, { target, source, amount, cause }) {
  const actor = Number(target || 0) | 0;
  if (!(actor > 0)) return false;

  const ch = world.get(actor, Channeling);
  if (!ch || String(ch.spellId || "") !== "drain_life") return false;

  try { world.remove(actor, Channeling); } catch {}

  const ae = world.get(actor, ActiveEffects);
  if (ae && Array.isArray(ae.effects)) {
    ae.effects = ae.effects.filter((e) => String(e?.key || "").toLowerCase() !== "drain_life_channel");
  }

  world.emit("spell:drain_life:break", {
    actor,
    targetId: Number(source || 0) | 0,
    spellId: "drain_life",
    reason: "damage_interrupt",
    amount: Number(amount || 0) | 0,
    cause: String(cause || ""),
  });

  world.emit("channeling:cancelled", {
    actor,
    spellId: "drain_life",
    reason: "damage_interrupt",
  });

  return true;
}

/** @param {import('../../lib/ecs-js/index.js').World} world */
export function channelingSystem(world) {
  let _isBlocked = null; // lazily built for breakOnNoLos checks
  for (const [id, ch] of world.query(Channeling)) {
    // Dead actors lose their channel
    const vit = world.get(id, Vitality);
    if (vit && (vit.hp | 0) <= 0) {
      try { world.remove(id, Channeling); } catch {}
      world.emit('channeling:cancelled', { actor: id, spellId: ch.spellId, reason: 'dead' });
      continue;
    }

    const interruption = getChannelInterruptionReason(world, id);
    if (interruption) {
      try { world.remove(id, Channeling); } catch {}
      world.emit('channeling:cancelled', {
        actor: id,
        spellId: ch.spellId,
        reason: interruption,
      });
      continue;
    }

    // breakOnMove: cancel if caster left anchor position
    if (ch.breakOnMove && ch.anchorX != null && ch.anchorY != null) {
      const cPos = world.get(id, Position);
      if (cPos && ((cPos.x | 0) !== (ch.anchorX | 0) || (cPos.y | 0) !== (ch.anchorY | 0))) {
        try { world.remove(id, Channeling); } catch {}
        world.emit('channeling:cancelled', {
          actor: id,
          spellId: ch.spellId,
          reason: 'caster_moved',
        });
        continue;
      }
    }

    // breakOnNoLos: cancel if caster no longer has LOS to target
    if (ch.breakOnNoLos && ch.targetId) {
      const cPos = world.get(id, Position);
      const tPos = world.get(ch.targetId, Position);
      if (cPos && tPos) {
        if (!_isBlocked) _isBlocked = blockedCallback(buildBlocksVisionMap(world));
        if (!hasLOS(cPos.x | 0, cPos.y | 0, tPos.x | 0, tPos.y | 0, _isBlocked)) {
          try { world.remove(id, Channeling); } catch {}
          world.emit('channeling:cancelled', {
            actor: id,
            spellId: ch.spellId,
            reason: 'los_break',
          });
          continue;
        }
      }
    }

    if (String(ch.mode || "cast") === "sustain") {
      const spell = getSpell(String(ch.spellId || ""));
      if (!spell) {
        try { world.remove(id, Channeling); } catch {}
        world.emit("channeling:cancelled", { actor: id, spellId: ch.spellId, reason: "invalid_spell" });
        continue;
      }

      const resource = spellCostResource(spell);
      const mana = world.get(id, Mana);
      const stamina = world.get(id, Stamina);
      const vitality = world.get(id, Vitality);
      const perTick = Math.max(0, Number(
        resource === "stamina"
          ? (ch.staminaPerTick ?? spellCostPerTick(spell))
          : resource === "life"
            ? (ch.lifePerTick ?? spellCostPerTick(spell))
            : (ch.manaPerTick ?? spellCostPerTick(spell))
      ));
      const have = Number(
        resource === "stamina"
          ? (stamina?.stamina ?? 0)
          : resource === "life"
            ? (vitality?.hp ?? 0)
            : (mana?.mana ?? 0)
      );
      const minLife = resource === "life" ? 1 : 0;
      if (have - perTick < minLife) {
        try { world.remove(id, Channeling); } catch {}
        world.emit("spell:oom", {
          actor: id,
          spellId: spell.id,
          need: perTick + minLife,
          have,
          costKind: resource === "stamina" ? "stamina" : resource === "life" ? "life" : "mana",
        });
        world.emit("channeling:cancelled", { actor: id, spellId: spell.id, reason: "oom" });
        continue;
      }

      if (resource === "stamina" && stamina) {
        stamina.stamina = have - perTick;
        stamina.regenCooldown = STAMINA_REGEN_COOLDOWN;
      } else if (resource === "life" && vitality) {
        vitality.hp = Math.max(1, have - perTick);
      } else if (mana) {
        mana.mana = have - perTick;
        mana.regenCooldown = MANA_REGEN_COOLDOWN;
      }

      try {
        runSpellScript(world, id, spell, {
          targetId: ch.targetId || id,
          x: ch.x,
          y: ch.y,
          _fromChanneling: true,
          _channelTick: true,
        });
      } catch {}

      world.emit("channeling:tick", {
        actor: id,
        spellId: spell.id,
        mode: "sustain",
        manaPerTick: resource === "mana" ? perTick : 0,
        staminaPerTick: resource === "stamina" ? perTick : 0,
        lifePerTick: resource === "life" ? perTick : 0,
        manaRemaining: Number(mana?.mana ?? 0),
        manaMax: effectiveMaxMana(world, id, mana),
        staminaRemaining: Number(stamina?.stamina ?? 0),
        staminaMax: effectiveMaxStamina(world, id, stamina),
        lifeRemaining: Number(vitality?.hp ?? 0),
      });
      continue;
    }

    ch.turnsRemaining -= 1;

    if (ch.turnsRemaining <= 0) {
      const itemAction = getUseAction(ch.itemActionId || "");
      if (itemAction) {
        try { world.remove(id, Channeling); } catch {}
        itemAction.onComplete(world, id, ch);
        world.emit('channeling:complete', { actor: id, spellId: ch.spellId || ch.itemActionId, mode: 'item_use' });
        continue;
      }

      // Channel complete — inject CastSpellIntent for castSpellSystem
      const castData = {
        spellId: ch.spellId,
        targetId: ch.targetId || id,
        _fromChanneling: true,
      };
      if (ch.x != null) castData.x = ch.x;
      if (ch.y != null) castData.y = ch.y;

      try { world.remove(id, Channeling); } catch {}
      try { world.add(id, CastSpellIntent, castData); } catch {}
      world.emit('channeling:complete', { actor: id, spellId: ch.spellId });
    } else {
      // Still channeling — emit progress for UI
      world.emit('channeling:tick', {
        actor: id,
        spellId: ch.spellId,
        mode: 'cast',
        turnsRemaining: ch.turnsRemaining,
        turnsTotal: ch.turnsTotal,
      });
    }
  }
}
import { KnockbackPending } from "../components/KnockbackPending.js";
import { Position } from "../components/Position.js";
import { isWalkable } from "../environment/dungeon/tileMap.js";
import { getTileQuerySnapshot } from "../utils/tileQueryCache.js";
import { statusStrength } from "../utils/statusFacade.js";

/**
 * Resolves pending knockback vectors into grid movement.
 *
 * Phase: intents (registered before movementSystem so knockback positions
 * are committed before the spatial index and blocking set are used by
 * movement resolution this tick).
 *
 * Each step of force attempts one tile of movement in (dx, dy).
 * Stops on the first blocked tile (solid terrain or solid entity).
 * Emits "moved" for each tile displaced and "knockback:stopped" if a
 * blocker was hit before force was exhausted.
 *
 * Consumes (removes) KnockbackPending after resolution.
 */
export function knockbackSystem(world) {
  const tiles = getTileQuerySnapshot(world);

  for (const [id, pos, kb] of world.query(Position, KnockbackPending)) {
    if (statusStrength(world, id, "stasis") > 0) {
      try { world.remove(id, KnockbackPending); } catch { /* */ }
      continue;
    }

    const dx    = Math.sign(kb.dx | 0);
    const dy    = Math.sign(kb.dy | 0);
    const force = Math.max(1, Math.min(5, kb.force | 0));

    let startX = pos.x | 0;
    let startY = pos.y | 0;
    let curX   = startX;
    let curY   = startY;
    let hitBlocker = false;

    for (let step = 0; step < force; step++) {
      const nx = curX + dx;
      const ny = curY + dy;
      const k  = `${nx},${ny}`;

      if (!isWalkable(nx, ny) || tiles.blockedByCell.has(k)) {
        hitBlocker = true;
        break;
      }

      curX = nx;
      curY = ny;
    }

    if (curX !== startX || curY !== startY) {
      const from = { x: startX, y: startY };
      const to   = { x: curX,   y: curY   };
      world.set(id, Position, to);
      world.emit("moved", { id, from, to });
    }

    if (hitBlocker) {
      world.emit("knockback:stopped", {
        id,
        at: { x: curX, y: curY },
        blockedAt: { x: curX + dx, y: curY + dy },
      });
    }

    try { world.remove(id, KnockbackPending); } catch { /* */ }
  }
}

/**
 * Teleport-throw the monster near the seen target and optionally collide.
 * Landing is always on a valid walkable/unblocked tile, never on top of target.
 *
 * @param {{ searchRadius?: number, fallbackSearchRadius?: number, cooldownTurns?: number }} [opts]
 */
export function selfThrowNearTargetOnSeen(opts = {}) {
  const searchRadius = Math.max(1, Number.isFinite(opts.searchRadius) ? (Number(opts.searchRadius) | 0) : 1);
  const fallbackSearchRadius = Math.max(searchRadius, Number.isFinite(opts.fallbackSearchRadius) ? (Number(opts.fallbackSearchRadius) | 0) : 2);
  const cooldownTurns = Math.max(0, Number.isFinite(opts.cooldownTurns) ? (Number(opts.cooldownTurns) | 0) : 0);
  const chance = Number.isFinite(opts.chance) ? Math.max(0, Math.min(1, opts.chance)) : 1;

  return (ctx) => {
    if (!ctx || ctx.cancelled) return;
    if (!ctx.canActThisTurn || ctx.hasQueuedMove) return;
    if (!worldChance(ctx.world, chance)) return;
    const from = ctx.actorPos;
    const target = ctx.targetPos;
    if (!from || !target) return;
    if (selfThrowOnCooldown(ctx.world, ctx.actor, ctx.target, cooldownTurns)) return;

    const exclude = [
      { x: target.x | 0, y: target.y | 0 },
      { x: from.x | 0, y: from.y | 0 },
    ];

    let landing = findNearestValidTileAround(ctx.world, target, { maxDistance: searchRadius, exclude });
    if (!landing && fallbackSearchRadius > searchRadius) {
      landing = findNearestValidTileAround(ctx.world, target, { maxDistance: fallbackSearchRadius, exclude });
    }

    if (!landing) {
      if (manhattan(from, target) === 1) {
        ctx.emit("bump:attack", { attacker: ctx.actor, target: ctx.target, via: "onSeen:self-throw" });
        markSelfThrowUsed(ctx.world, ctx.actor, ctx.target, cooldownTurns);
        ctx.setHandled(true);
      }
      return;
    }

    ctx.world.set(ctx.actor, Position, { x: landing.x | 0, y: landing.y | 0 });
    ctx.emit("moved", {
      id: ctx.actor,
      from: { x: from.x | 0, y: from.y | 0 },
      to: { x: landing.x | 0, y: landing.y | 0 },
    });
    ctx.emit("item:thrown", {
      itemId: ctx.actor,
      from: { x: from.x | 0, y: from.y | 0 },
      to: { x: landing.x | 0, y: landing.y | 0 },
      targetId: ctx.target,
      source: "monster:onSeen",
      mode: "self-throw",
    });

/**
 * @param {import("../../../lib/ecs-js/index.js").World} world
 * @param {number} x
 * @param {number} y
 * @returns {number}
 */
function findFireHazardAt(world, x, y) {
  for (const [id, pos, hazard] of world.query(Position, HazardArea)) {
    if (!pos || !hazard) continue;
    if ((pos.x | 0) !== (x | 0) || (pos.y | 0) !== (y | 0)) continue;
    if (String(hazard.kind || "").toLowerCase() !== "fire") continue;
    if ((hazard.radius | 0) !== 0) continue;
    return id | 0;
  }
  return 0;
}

/**
 * Gaze aura: starts a channeled gaze_beam spell when the eye has LOS.
 * The channeling system handles countdown, interruption (stun/silence/LOS break),
 * and fires the gaze_beam script on completion (stun + mindwipe).
 * Each turn in LOS emits escalating `proc:gaze:message` and `proc:gaze:charging`
 * events for UI wiring.
 *
 * @param {number} [exposureTurns=8] - channel duration (turns before gaze fires)
 */
export function gazeOnLOS(exposureTurns = 8) {
  const castTime = Math.max(1, Math.trunc(exposureTurns));

  const MESSAGES = [
    "The Floating Eye's unblinking gaze washes over you.",
    "Your thoughts feel sluggish under its stare...",
    "The eye's gaze presses deeper into your mind.",
    "Your concentration is slipping away...",
    "The Floating Eye's gaze sears into your mind!",
  ];

  return (ctx) => {
    if (!ctx || ctx.cancelled) return;
    if (!ctx.canActThisTurn) return;
    const world = ctx.world;
    const actor = ctx.actor | 0;
    const target = ctx.target | 0;
    const now = (Number(world.step) || 0) | 0;

    // If already channeling gaze_beam, emit progress events
    const ch = world.has(actor, Channeling) ? world.get(actor, Channeling) : null;
    if (ch && String(ch.spellId || '') === 'gaze_beam') {
      const elapsed = Math.max(0, (ch.turnsTotal | 0) - (ch.turnsRemaining | 0));
      const msgIdx = Math.min(elapsed, MESSAGES.length - 1);
