  }
  if (wetIntercept?.consumed) {
    ctx.mutate.consume(itemId, actor);
    ctx.io.emit("item:used", { actor, itemId });
    metrics.consumed = true;
    metrics.path = "waterIntercept";
    return {
      metrics,
      payload: {
        defId: null,
        path: "waterIntercept",
        hookResult: wetIntercept,
      },
    };
