  if (!state.data.ratatoskr || typeof state.data.ratatoskr !== "object") {
    state.data.ratatoskr = {
      state: RATATOSKR_STATES.dormant,
      nextAppearTurn: (world.step | 0) + APPEAR_MIN_TURNS,
      visits: 0,
      lastBarkTurn: -9999,
      vanishTurn: 0,
      trigger: "",
    };
