  if (!state.data.ratatoskr.state) state.data.ratatoskr.state = RATATOSKR_STATES.dormant;
  if (!Number.isFinite(Number(state.data.ratatoskr.vanishTurn))) state.data.ratatoskr.vanishTurn = 0;
