const r = await tools.exec_command({
  cmd: "ls -la | sed -n '1,100p'; sed -n '1,220p' deno.json 2>/dev/null; sed -n '1,220p' README.md | rg -n \"serve|dev|8181|port|Deno\" -C 2; rg -n \"8181|--port|listen\\(|serveDir|static\" . --glob '!src/lib/**' --glob '!node_modules/**' --glob '*.{js,mjs,json,md,sh}' | head -160",
  workdir: "/home/pjensen/Repos/JSHack",
  yield_time_ms: 10000,
  max_output_tokens: 16000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "python3 -m http.server 8181",
  workdir: "/home/pjensen/Repos/JSHack",
  tty: true,
  yield_time_ms: 1000,
  max_output_tokens: 2000
});
text(JSON.stringify(r));

const r = await tools.exec_command({
  cmd: "python3 -m http.server 8181",
  workdir: "/home/pjensen/Repos/JSHack",
  tty: true,
  yield_time_ms: 1000,
  max_output_tokens: 2000,
  sandbox_permissions: "require_escalated",
  justification: "May I start the local static server on port 8181 so I can inspect the actual browser build and reproduce stasis against the served runtime?",
  prefix_rule: ["python3", "-m", "http.server"]
});
text(JSON.stringify(r));

const r = await tools.exec_command({
  cmd: "python3 -m http.server 8181 --bind 127.0.0.1",
  workdir: "/home/pjensen/Repos/JSHack",
  tty: true,
  yield_time_ms: 1000,
  max_output_tokens: 2000,
  sandbox_permissions: "require_escalated",
  justification: "May I start the repository’s static server bound only to 127.0.0.1:8181 to inspect the served runtime locally?",
  prefix_rule: ["python3", "-m", "http.server"]
});
text(JSON.stringify(r));

const results = await Promise.all([
  tools.exec_command({cmd:"ss -ltnp | rg ':8181\\b' || true; curl -4 -v --max-time 3 http://127.0.0.1:8181/ 2>&1 | sed -n '1,80p'; curl -6 -g -v --max-time 3 http://[::1]:8181/ 2>&1 | sed -n '1,80p'",workdir:"/home/pjensen/Repos/JSHack",yield_time_ms:10000,max_output_tokens:10000}),
  tools.exec_command({cmd:"ps -efww | rg 'python|deno|http.server|8181' | rg -v 'rg ' || true; fuser -v 8181/tcp 2>/dev/null || true",workdir:"/home/pjensen/Repos/JSHack",yield_time_ms:10000,max_output_tokens:6000})
]);
for (const r of results) text(r.output);

const r = await tools.exec_command({
  cmd: "curl -sS -D - http://127.0.0.1:8181/ | sed -n '1,100p'",
  workdir: "/home/pjensen/Repos/JSHack",
  yield_time_ms: 10000,
  max_output_tokens: 10000,
  sandbox_permissions: "require_escalated",
  justification: "May I query the already-running local service on 127.0.0.1:8181 to inspect the actual served build?",
  prefix_rule: ["curl"]
});
text(r.output);

