} from "../../rules/environment/dungeon/constants.js";

const TILE_KIND_TO_ID = Object.freeze({
  floor: TILE_FLOOR,
  wall: TILE_WALL,
  lava: TILE_LAVA,
  shallow: TILE_SHALLOW_WATER,
