  console.registerCommand('heal', 'Fully heal the player', () => {
    const pe = playerEntity(world);
    if (!pe) return 'No player entity found.';
    const vit = world.get(pe.id, Vitality);
    if (!vit) return 'Player has no Vitality component.';
    vit.hp = vit.maxHp;
